#include <linux/usb.h>
#include <linux/videodev2.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <linux/v4l2-dv-timings.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-ioctl.h>
#include <media/v4l2-fh.h>
#include <media/videobuf2-v4l2.h>

struct airspy_dev;
struct airspy_dev {
    struct mutex lock;
    struct v4l2_device v4l2_dev;
    struct video_device vdev;
    struct v4l2_ctrl_handler ctrl_handler;
    int board_id;
    int fw_version;
    struct vb2_queue vq;
};

static int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);

    v4l2_ctrl_handler_init(&dev->ctrl_handler, 16);
    dev->v4l2_dev.ctrl_handler = &dev->ctrl_handler;
    if (dev->ctrl_handler.error) {
        ret = dev->ctrl_handler.error;
        goto err_ctrl_handler;
    }

    ret = usb_set_interface(intf, 0, 0);
    if (ret < 0)
        goto err_usb_set_interface;

    ret = -ENODEV;
    if (usb_control_msg(usb_get_dev(intf->cur_altsetting->actconfig->interface), USB_DIR_OUT | USB_TYPE_VENDOR,
                        0, 0, 0, NULL, 0, USB_CTRL_SET_TIMEOUT) != 0)
        goto err_usb_control_msg;

    dev->board_id = 0;
    dev->fw_version = 0;

    ret = vb2_queue_init(&dev->vq);
    if (ret < 0)
        goto err_vb2_queue_init;

    strscpy(dev->v4l2_dev.name, "airspy", sizeof(dev->v4l2_dev.name));
    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto err_v4l2_device_register;

    dev->vdev.ctrl_handler = &dev->ctrl_handler;
    dev->vdev.lock = &dev->lock;
    video_set_drvdata(&dev->vdev, dev);

    ret = video_register_device(&dev->vdev, VFL_TYPE_VIDEO, 0);
    if (ret < 0)
        goto err_video_register_device;

    dev_info(&intf->dev, "Airspy registered with board ID %d and firmware version %d\n",
             dev->board_id, dev->fw_version);

    return 0;

err_video_register_device:
    v4l2_device_unregister(&dev->v4l2_dev);
err_v4l2_device_register:
    vb2_queue_release(&dev->vq);
err_vb2_queue_init:
err_usb_control_msg:
err_usb_set_interface:
err_ctrl_handler:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(usb_ifnum_to_index(intf));
    dev->interface = intf;

    ret = airspy_init_ctrl_in(dev);
    if (ret < 0)
        goto err_free_dev;

    mutex_init(&dev->lock);

    ret = airspy_video_register(dev);
    if (ret < 0)
        goto err_deinit_ctrl;

    ret = airspy_ctrl_init(dev);
    if (ret < 0)
        goto err_unregister_video;

    usb_set_intfdata(intf, dev);

    dev_info(&dev->udev->dev, "Airspy device registered (Board ID: %08x, Firmware: %08x)\n",
             dev->board_id, dev->firmware_version);

    return 0;

err_unregister_video:
    airspy_video_unregister(dev);
err_deinit_ctrl:
    airspy_deinit_ctrl_in(dev);
err_free_dev:
    kfree(dev);
    return ret;
}

#include <linux/usb.h>
#include <linux/videodev2.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <media/v4l2-device.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-async.h>
#include <media/v4l2-ioctl.h>
#include <media/v4l2-fh.h>

#include "airspy.h"

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    mutex_init(&dev->v4l2_mutex);

    usb_set_intfdata(intf, dev);

    dev->udev = usb_get_dev(usb_ifnum_to_index(intf->cur_altsetting));
    dev->interface = intf;

    ret = airspy_init_ctrls(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_setup_video_queue(dev);
    if (ret < 0)
        goto error_free_ctrls;

    ret = airspy_register_v4l2_device(dev);
    if (ret < 0)
        goto error_cleanup_video_queue;

    ret = airspy_send_control_messages(dev);
    if (ret < 0)
        goto error_unregister_v4l2;

    dev_info(&dev->interface->dev, "Airspy board ID %d, firmware version %d.%d",
             dev->board_id, dev->fw_version >> 8, dev->fw_version & 0xFF);

    return 0;

error_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
error_cleanup_video_queue:
    airspy_cleanup_video_queue(dev);
error_free_ctrls:
    airspy_free_ctrls(dev);
error_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct airspy_device *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    init_waitqueue_head(&dev->wait_queue);

    usb_fill_int_urb(&dev->irq_urb, dev->udev, usb_rcvintpipe(dev->udev, 1),
                     dev->irq_buffer, sizeof(dev->irq_buffer),
                     airspy_irq_handler, dev, 10);

    ret = usb_submit_urb(&dev->irq_urb, GFP_KERNEL);
    if (ret < 0) {
        kfree(dev);
        return ret;
    }

    ret = airspy_get_device_id(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_get_version(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_setup_video_device(dev);
    if (ret < 0)
        goto error_unregister_v4l2;

    dev_info(&intf->dev, "Airspy device initialized (board ID: %d, firmware: %d.%02d)\n",
             dev->board_id, dev->firmware_version >> 8, dev->firmware_version & 0xFF);

    usb_set_intfdata(intf, dev);
    return 0;

error_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
error_free_dev:
    kfree(dev);
    return ret;
}

#include <linux/usb.h>
#include <linux/videodev2.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-ioctl.h>
#include <media/v4l2-fh.h>
#include <media/videobuf2-core.h>

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->mutex);
    mutex_init(&dev->lock);
    INIT_LIST_HEAD(&dev->buf_list);

    ret = usb_set_interface(dev->udev, 0, 0);
    if (ret < 0)
        goto err_free_dev;

    ret = airspy_usb_control_msg(dev, AIRSPY_USB_REQ_GET_FIRMWARE_VERSION,
                                 0, 0, dev->firmware_version,
                                 sizeof(dev->firmware_version));
    if (ret < 0)
        goto err_free_dev;

    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto err_free_dev;

    ret = videobuf2_queue_init(&dev->vb_queue, &airspy_vb2_queue_ops,
                               &dev->usb->dev, NULL,
                               V4L2_BUF_TYPE_VIDEO_CAPTURE,
                               V4L2_MEMORY_MMAP, NULL, dev, NULL);
    if (ret < 0)
        goto err_unreg_v4l2;

    ret = airspy_init_ctrls(dev);
    if (ret < 0)
        goto err_cleanup_vb2;

    usb_set_intfdata(intf, dev);

    printk(KERN_INFO "Airspy: Board ID %d, firmware version %s\n",
           dev->board_id, dev->firmware_version);

    return 0;

err_cleanup_vb2:
    videobuf2_queue_release(&dev->vb_queue);
err_unreg_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
err_free_dev:
    kfree(dev);
    return ret;
}
